'use strict';
const SEED=JSON.parse(document.getElementById('seed-data').textContent),KEY='happy-sport-prototype-v1';
const clone=x=>JSON.parse(JSON.stringify(x));
let state;try{state=JSON.parse(localStorage.getItem(KEY)||'null')}catch{};
if(!state||state.version!==1)state={version:1,workouts:clone(SEED.workouts),measurements:clone(SEED.measurements),customExercises:[],templates:[],active:null,energy:{burn:0,intake:0,steps:0,training:0,minutes:0},demoPulse:false};
let view='diary',journalTab='workouts',libraryTab='exercises',libraryScope='all',category='all',query='',selectedDate=dayNow(),detailId=null,measureDate=dayNow(),period='first',amplify=3,historyFilter='all',sheetKind='',undoAction=null,toastTimer,priorFocus;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:1}),icon=n=>sportIconMarkup(n)||SEED.icons[n]||SEED.icons['barbell'];
const allExercises=()=>[...SEED.exercises.map(e=>state.exerciseOverrides?.[e.id]||e),...state.customExercises],exercise=id=>allExercises().find(x=>x.id===id),kindIcon=k=>({sea:'waves',bars:'person-simple',gym:'barbell',cardio:'person-simple-walk'}[k]||'barbell');
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'}),shortDate=d=>new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'}).replace('.','');
function localNow(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date()).replace(' ','T')}
function dayNow(){return localNow().slice(0,10)}
function secondsBetween(a,b){return Math.round((new Date(b)-new Date(a))/1000)}
function durationText(sec){sec=Math.max(0,Number(sec)||0);const m=Math.floor(sec/60),h=Math.floor(m/60);return h?`${h} ч ${m%60} мин`:m?`${m} мин`:`${Math.round(sec)} сек`}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Браузер не сохранил данные. Выгрузи копию в профиле.')}}
function toast(text,undo=null){clearTimeout(toastTimer);undoAction=undo;$('#toast-root').innerHTML=`<div class="toast"><span>${esc(text)}</span>${undo?'<button data-action="undo">Отменить</button>':''}</div>`;toastTimer=setTimeout(()=>{$('#toast-root').innerHTML='';undoAction=null},6000)}
function goto(v){closeSheet();view=v;render();window.scrollTo({top:0,behavior:'instant'})}
function renderTop(title,date=true){return `<header class="top"><div><div class="brand">happy sport</div><h1>${title}</h1></div>${date?`<label class="date-pill">${icon('calendar-blank')}<span>${dateLabel(selectedDate)}</span><input aria-label="День дневника" type="date" value="${selectedDate}" id="day-picker"></label>`:''}</header>`}
function backTop(title){return `<header class="back-heading"><button class="icon-btn" data-action="back" aria-label="Назад">${icon('arrow-left')}</button><h1>${esc(title)}</h1></header>`}
function nav(){const items=[['diary','calendar-blank','Дневник'],['library','books','Библиотека'],null,['journal','notebook','Журнал'],['profile','user-circle','Профиль']];$('#dock').innerHTML=items.map(i=>i?`<button class="nav-btn ${view===i[0]?'selected':''}" data-action="navigate" data-view="${i[0]}" aria-current="${view===i[0]?'page':'false'}">${icon(i[1])}<span>${i[2]}</span></button>`:'<div></div>').join('')+`<button class="mic-fab" data-action="voice" aria-label="Записать голосом или текстом">${icon('microphone')}</button>`;$('#active-banner').innerHTML=state.active&&view!=='active'?`<div class="active-banner"><span class="row">${icon('timer')}<b style="font-size:12px">${esc(state.active.title)}</b></span><button data-action="resume">Продолжить</button></div>`:''}
function render(){nav();$('#page').innerHTML=({diary:renderDiary,library:renderLibrary,journal:renderJournal,profile:renderProfile,active:renderActive,detail:renderDetail}[view]||renderDiary)();updateClock()}
function arc(r,part,color,width=12){const len=2*Math.PI*r,p=Math.max(0,Math.min(1,part));return `<circle cx="125" cy="125" r="${r}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round" stroke-dasharray="${len*.76*p} ${len}" transform="rotate(133.2 125 125)"/>`}
function renderDiary(){const e=state.energy,dayWork=state.workouts.filter(w=>w.start.slice(0,10)===selectedDate);return renderTop('Дневник')+`<section class="card energy"><div class="energy-header"><span>Энергия дня</span><button class="badge demo" data-action="energy">Демо ${icon('sliders-horizontal')}</button></div><div class="energy-layout"><div class="ring" role="img" aria-label="Демо: расход ${e.burn}, питание ${e.intake} килокалорий"><svg viewBox="0 0 250 250">${arc(106,1,'#ffffff24',14)}${arc(99,1,'#ffffff14',14)}${arc(106,e.burn/3200,'#8af7e9cc',15)}${arc(99,e.intake/3200,'#f5b0e2c9',15)}</svg><div class="ring-center"><small>расход</small><strong>${fmt(e.burn)}</strong><span class="unit">ккал</span></div></div><div class="metrics"><div class="metric"><span class="dot"></span><b>${fmt(e.steps)}</b><small>шагов</small></div><div class="metric"><span class="dot pink"></span><b>${fmt(e.training)}</b><small>ккал на тренировке</small></div><div class="metric"><span class="dot yellow"></span><b>${fmt(e.minutes)} <span style="font-size:11px">мин</span></b><small>активности</small></div></div></div><div class="energy-legend"><span><i class="dot"></i> Расход</span><span><i class="dot pink"></i> Питание · Happy Meal</span></div><div class="balance"><span>Потреблено <strong style="color:white">${fmt(e.intake)} ккал</strong></span><button class="text-btn" data-action="energy">Баланс ${fmt(e.intake-e.burn)} ${icon('caret-right')}</button></div></section><div class="quick-actions"><button class="button primary" data-action="start-menu">${icon('play')} Начать тренировку</button><button class="button" data-action="past">${icon('plus')} Добавить запись</button></div><div class="section-title"><h2>Мои тренировки</h2><button class="text-btn" data-action="templates">Все ${icon('caret-right')}</button></div><div class="pin-grid">${[['sea','waves','Море','Плавание'],['gym','barbell','Зал','Силовая'],['bars','person-simple','Турники','Свой вес']].map(([k,i,t,s])=>`<button class="card pin" data-action="preview-template" data-id="${k}" aria-label="${k==='sea'?'Плавание в море':k==='gym'?'Тренажёрный зал':'Турники'}"><span class="pin-icon">${icon(i)}</span><b>${t}</b><small>${s}</small></button>`).join('')}</div><button class="card voice-prompt" data-action="voice">${icon('microphone')}<span class="grow"><b>Скажи, что сделал</b><small>«Жим 60 кг, три подхода по десять»</small></span>${icon('caret-right')}</button><div class="section-title"><h2>${dayWork.length?'Тренировки за день':'Последняя тренировка'}</h2><button class="text-btn" data-action="navigate" data-view="journal">Журнал ${icon('caret-right')}</button></div><div class="stack">${(dayWork.length?dayWork:[...state.workouts].sort((a,b)=>b.start.localeCompare(a.start)).slice(0,1)).map(w=>workoutCard(w,true)).join('')||'<div class="card empty">Здесь появятся твои тренировки.</div>'}</div><p class="fineprint">Показатели энергии — пример синхронизации. Энергия тренировки уже входит в общий расход.</p>`}
function workoutCard(w,showDate=false){const sets=w.exercises.reduce((n,e)=>n+e.sets.filter(s=>s.done).length,0);return `<button class="card workout-row" data-action="open-workout" data-id="${esc(w.id)}"><span class="symbol">${icon(workoutIconName(w))}</span><div class="grow">${showDate?`<div class="record-date">${dateLabel(w.start.slice(0,10))} · ${w.start.slice(11,16)}</div>`:''}<h3>${esc(w.title)}</h3><div class="sub">${durationText(w.duration)}${w.exercises.length?` · ${sets} подход${plural(sets)}`:''}${w.demo?' · Демо':''}</div></div>${icon('caret-right')}</button>`}
function plural(n){return n%10===1&&n%100!==11?'':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'а':'ов'}
function renderLibrary(){return renderTop('Библиотека',false)+`<div class="segmented">${[['exercises','Упражнения'],['templates','Тренировки'],['activities','Виды спорта']].map(([k,t])=>`<button class="${libraryTab===k?'selected':''}" data-action="library-tab" data-id="${k}">${t}</button>`).join('')}</div>${libraryTab==='templates'?renderTemplates():libraryTab==='activities'?renderActivities():`<label class="search">${icon('magnifying-glass')}<input id="library-search" placeholder="Название, оборудование…" value="${esc(query)}" aria-label="Поиск упражнений"></label>${muscleGroupChips()}<div class="chips">${[['all','Оборудование'],['barbell','Штанга'],['dumbbell','Гантели'],['machine','Тренажёры'],['bodyweight','Без оборудования'],['cardio','Кардио'],['mobility','Разминка и заминка']].map(([k,t])=>`<button data-action="category" data-id="${k}" class="${category===k?'selected':''}">${t}</button>`).join('')}</div><div id="library-results">${libraryResults()}</div><button class="button dashed" data-action="custom-exercise" style="margin-top:15px">${icon('plus')} Создать своё упражнение</button>`}`}
function matches(e,q){return [e.name,e.en,...(e.aliases||[]),...(e.equipment||[]).map(x=>SEED.equipment[x]||x)].join(' ').toLowerCase().replaceAll('ё','е').includes(q.toLowerCase().replaceAll('ё','е'))}
function filteredExercises(q=query){return allExercises().filter(e=>matches(e,q)&&(category==='all'||(category==='barbell'&&e.id.startsWith('barbell'))||(category==='dumbbell'&&e.id.startsWith('dumbbell'))||(category==='machine'&&/^(machine|cable|smith)/.test(e.id))||(category==='bodyweight'&&e.category==='Без оборудования')||(category==='cardio'&&e.category==='Кардио')||(category==='mobility'&&(/stretch|cat-cow|hip-90|ankle|thoracic/.test(e.id)))))}
function exerciseCard(e,action='exercise-detail'){return `<button class="card exercise-card" data-action="${action}" data-id="${esc(e.id)}"><span class="placeholder sport-thumbnail">${icon(exerciseSportIcon(e))}</span><span class="grow"><h3>${esc(e.name)}</h3><small>${esc(e.category)}${e.scope==='user'?' · Моё':''}</small></span>${icon('caret-right')}</button>`}
function libraryResults(){const arr=filteredExercises();return `<div class="library-count">${arr.length} упражнений</div><div class="exercise-list">${arr.map(e=>exerciseCard(e)).join('')||'<div class="empty">Ничего не найдено. Можно создать своё упражнение.</div>'}</div>`}
const baseTemplates=[{id:'sea',title:'Плавание в море',kind:'sea',description:'Разминка на берегу, плавание, заминка',items:[['shoulder-stretch','warmup',1],['swimming','main',1],['calf-stretch','cooldown',1]]},{id:'gym',title:'Тренажёрный зал',kind:'gym',description:'Пример: разминка, три упражнения, заминка',items:[['walking','warmup',1],['barbell-bench-press','main',3],['barbell-back-squat','main',3],['cable-seated-row','main',3],['chest-stretch','cooldown',1]]},{id:'bars',title:'Турники',kind:'bars',description:'Разминка, подтягивания, отжимания, заминка',items:[['jumping-jack','warmup',1],['pull-up','main',3],['push-up','main',3],['shoulder-stretch','cooldown',1]]}];
const templates=()=>[...baseTemplates.map(t=>state.templateOverrides?.[t.id]||t),...state.templates];
function renderTemplates(){return `<p class="sheet-info">Шаблон задаёт порядок. Веса, подходы и упражнения можно менять прямо во время тренировки.</p>${templates().map(t=>`<article class="card template-card"><div class="row">${icon(kindIcon(t.kind))}<div class="grow"><h3>${esc(t.title)}</h3><small class="muted">${esc(t.description||`${t.items.length} упражнений · мой шаблон`)}</small></div></div><button class="button" data-action="preview-template" data-id="${esc(t.id)}">Открыть тренировку ${icon('caret-right')}</button></article>`).join('')}<button class="button dashed" data-action="new-template">${icon('plus')} Создать тренировку</button>`}
function renderActivities(){return `<p class="sheet-info">57 видов активности. Можно вести упражнения внутри тренировки или записать время и дистанцию.</p><div class="exercise-list">${SEED.activities.map(a=>`<button class="card exercise-card" data-action="activity-start" data-id="${esc(a.id)}"><span class="placeholder">${icon(a.category==='aquatic'?'waves':'person-simple')}</span><span class="grow"><h3>${esc(a.name_ru)}</h3><small>Свободная тренировка</small></span>${icon('plus')}</button>`).join('')}</div>`}
function renderJournal(){return renderTop(journalTab==='measurements'?'Замеры':'Журнал',false)+`<div class="segmented"><button data-action="journal-tab" data-id="workouts" class="${journalTab==='workouts'?'selected':''}">Тренировки</button><button data-action="journal-tab" data-id="measurements" class="${journalTab==='measurements'?'selected':''}">Замеры</button></div>`+(journalTab==='measurements'?renderMeasurements():renderHistory())}
function renderHistory(){const filtered=state.workouts.filter(w=>historyFilter==='all'||w.kind===historyFilter).sort((a,b)=>b.start.localeCompare(a.start));let month='';const recent=state.workouts.filter(w=>w.start.startsWith(dayNow().slice(0,7)));return `<div class="card"><div class="row between"><h3>${new Date(dayNow()+'T12:00').toLocaleDateString('ru-RU',{month:'long'})}</h3><span class="badge">Твоя история</span></div><div class="summary-numbers"><div><strong>${recent.length}</strong><small>тренировок</small></div><div><strong>${durationText(recent.reduce((s,w)=>s+w.duration,0))}</strong><small>по записям</small></div></div></div><div class="section-title"><h2>История</h2><button class="text-btn" data-action="past">${icon('plus')} Добавить</button></div><div class="chips">${[['all','Все'],['gym','Зал'],['sea','Море'],['bars','Турники']].map(([k,t])=>`<button data-action="history-filter" data-id="${k}" class="${historyFilter===k?'selected':''}">${t}</button>`).join('')}</div><div class="stack">${filtered.map(w=>{const m=w.start.slice(0,7);let head='';if(m!==month){month=m;head=`<div class="month-label">${new Date(m+'-01T12:00').toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</div>`}return head+workoutCard(w,true)}).join('')||'<div class="empty">Пока нет тренировок этого вида.</div>'}</div>`}
const MF=[['neck','Шея'],['shoulders','Плечи'],['chest','Грудь'],['underChest','Под грудью'],['bicepsR','Бицепс · правый'],['bicepsL','Бицепс · левый'],['forearmR','Предплечье · правое'],['forearmL','Предплечье · левое'],['upperAbs','Верх живота'],['waist','Талия'],['lowerAbs','Низ живота'],['hips','Бёдра'],['thighR','Бедро · правое'],['thighL','Бедро · левое'],['calfR','Голень · правая'],['calfL','Голень · левая'],['weight','Вес']];
function measurePair(){const sorted=[...state.measurements].sort((a,b)=>a.date.localeCompare(b.date)),cur=sorted.find(m=>m.date===measureDate)||sorted.at(-1),past=sorted.filter(m=>m.date<cur.date);let old;if(period==='first')old=past[0];else if(period==='previous')old=past.at(-1);else{const d=new Date(cur.date+'T12:00');d.setMonth(d.getMonth()-(period==='month'?1:3));old=[...past].reverse().find(x=>x.date<=d.toISOString().slice(0,10))||past[0]}return {cur,old:old||cur}}
// Synthetic round reference dimensions for illustration; never personal measurements.
function bodyPath(values,baseline){const v=(k,def,scale=1)=>{let val=values[k]??baseline[k]??def,base=baseline[k]??val;return def+(base-def)*scale+(val-base)*scale*amplify};const shoulder=55+(v('shoulders',120)-120)*.6,chest=43+(v('chest',100)-100)*.58,waist=32+(v('waist',80)-80)*.56,hip=42+(v('hips',100)-100)*.48,arm=14+(v('bicepsR',30)-30)*.7,thigh=22+(v('thighR',50)-50)*.5,calf=14+(v('calfR',30)-30)*.7;let half=`M 150 25 C 168 25 171 39 168 53 C 166 65 159 68 160 76 L ${150+shoulder-10} 88 Q ${150+shoulder} 91 ${150+shoulder+4} 106 L ${150+shoulder+arm+14} 189 Q ${150+shoulder+arm+18} 207 ${150+shoulder+arm+10} 216 Q ${150+shoulder+arm} 223 ${150+shoulder+arm-2} 209 L ${150+chest+6} 132 Q ${150+chest} 161 ${150+waist} 194 Q ${150+waist-1} 207 ${150+hip} 226 Q ${150+hip+3} 245 ${150+19+thigh} 269 L ${150+18+calf} 333 Q ${150+19+calf} 351 ${150+28} 358 Q ${150+39} 366 ${150+34} 373 L 163 373 Q 159 371 162 353 L 154 280 Q 150 251 150 249`;let right=half+' Z';return right}
function silhouette(values,baseline,color,opacity){const d=bodyPath(values,baseline);return `<g fill="${color}" opacity="${opacity}"><path d="${d}"/><path d="${d}" transform="translate(300 0) scale(-1 1)"/></g>`}
function renderMeasurements(){const {cur,old}=measurePair(),changed=MF.filter(([k])=>cur.values[k]!=null&&old.values[k]!=null&&cur.values[k]!==old.values[k]).length;return `<div class="row between" style="margin-bottom:13px"><label class="date-pill">${icon('calendar-blank')}<span>${dateLabel(cur.date)}</span><select id="measure-date" aria-label="Дата замера" style="position:absolute;inset:0;opacity:0;width:100%">${[...state.measurements].reverse().map(m=>`<option ${m.date===cur.date?'selected':''} value="${m.date}">${dateLabel(m.date)}</option>`).join('')}</select></label><button class="text-btn" data-action="add-measure">${icon('plus')} Замер</button></div><div class="card measure-outer"><div class="body-viz"><div class="legend"><span><i class="dot now"></i> Сейчас · ${shortDate(cur.date)}</span><span><i class="dot before"></i> Было · ${shortDate(old.date)}</span><span><i class="dot same"></i> Совпадает</span></div><div class="amplify"><button data-action="amplify" data-id="1" class="${amplify===1?'selected':''}">1:1</button><button data-action="amplify" data-id="3" class="${amplify===3?'selected':''}">×3</button></div><svg class="body-chart" viewBox="0 0 300 405" role="img" aria-label="Схематическое сравнение замеров, разница увеличена в ${amplify===1?'1 раз':'3 раза'}"><ellipse cx="150" cy="389" rx="56" ry="5" fill="#6b8bb91c"/><defs><clipPath id="old-body"><path d="${bodyPath(old.values,old.values)}"/><path d="${bodyPath(old.values,old.values)}" transform="translate(300 0) scale(-1 1)"/></clipPath></defs>${silhouette(old.values,old.values,'#61cce8',.9)}${silhouette(cur.values,old.values,'#e385d0',.85)}<g clip-path="url(#old-body)">${silhouette(cur.values,old.values,'#6a7dce',1)}</g></svg><div class="body-caption">Схематично · ${amplify===3?'разница увеличена ×3':'без усиления разницы'}</div></div><button class="button" data-action="changes">${icon('clock-counter-clockwise')} Что изменилось <span style="opacity:.65;margin-left:auto">${changed} ${icon('caret-right')}</span></button><div class="segmented periods">${[['previous','Прошлый'],['month','Месяц'],['3months','3 месяца'],['first','Первый']].map(([k,t])=>`<button data-action="period" data-id="${k}" class="${period===k?'selected':''}">${t}</button>`).join('')}</div></div><div class="card measure-table"><div class="measure-heading"><span>Сейчас · ${shortDate(cur.date)}</span><span>К ${shortDate(old.date)}</span></div>${measureRows(cur,old)}</div><p class="comparison-note">${esc(cur.source)}. ${esc(cur.note||'')}<br>Сравнение: ${esc(old.source)}. Нет замера в выбранную дату — оставляем пропуск.</p><button class="button" data-action="edit-measure">${icon('pencil-simple')} Исправить замеры</button>`}
function measureRows(cur,old){return MF.filter(([k])=>cur.values[k]!=null||old.values[k]!=null).map(([k,n])=>{const a=cur.values[k],b=old.values[k],delta=a!=null&&b!=null?a-b:null;return `<div class="measure-row"><span>${n}</span><b>${a!=null?fmt(a):'—'} <small style="font-size:9px;font-weight:500">${k==='weight'?'кг':'см'}</small></b><span class="delta ${delta==null?'missing':''}">${delta==null?'нет пары':delta===0?'—':(delta>0?'+':'−')+fmt(Math.abs(delta))}</span></div>`}).join('')}
const phaseNames={warmup:'Разминка',main:'Основная часть',cooldown:'Заминка'};
function isTimed(e){return /duration|hold|distance_time|swim|ergometer|treadmill/.test(exercise(e.id)?.profile||'')}
function isLoaded(e){return /load|assisted/.test(exercise(e.id)?.profile||'')}
function volume(w){return w.exercises.reduce((n,e)=>n+e.sets.filter(s=>s.done).reduce((a,s)=>a+(s.weight||0)*(s.reps||0),0),0)}
function pulseCard(){return `<section class="card pulse-card"><div class="pulse-top"><div><div class="pulse-label">${icon('heartbeat')} Пульс</div><strong class="pulse-value" id="pulse-value">${state.demoPulse?'124':'—'} <small>уд/мин</small></strong></div><button class="badge" data-action="pulse-toggle">${state.demoPulse?'Демо · выключить':'Включить демо'}</button></div><div class="pulse-scale">${['#b1d7ec','#80ded7','#e1e69c','#fac58e','#efa5cc'].map(c=>`<span style="background:${c}"></span>`).join('')}${state.demoPulse?'<i id="pulse-marker" style="left:46%"></i>':''}</div><div class="scale-labels"><span>50</span><span>80</span><span>110</span><span>140</span><span>170</span><span>200</span></div><div class="sub" style="font-size:10px;margin-top:9px">${state.demoPulse?'Симуляция показаний · шкала уд/мин, не персональные зоны':'Датчик не подключён · показаний пока нет'}</div></section>`}
function renderActive(){const w=state.active;if(!w){view='diary';return renderDiary()}return `<div class="active-workout"><div class="current-bar row between"><div><div class="active-timer">${workoutPauseButton(w)}<div class="clock" id="active-clock" role="timer">00:00</div></div></div><button class="button primary" style="width:auto;min-height:41px;padding:10px 14px" data-action="finish">${icon('check')} Завершить</button></div>${pulseCard()}${w.exercises.map((e,ei)=>activeExercise(e,ei)).join('')}<button class="button dashed" data-action="add-exercise" data-phase="main">${icon('plus')} Добавить упражнение</button><label class="field">Заметка о тренировке<textarea id="active-note" placeholder="Как прошла тренировка, самочувствие…">${esc(w.notes||'')}</textarea></label><button class="button" data-action="save-template">${icon('copy')} Сохранить как шаблон</button><button data-action="discard-active" class="text-btn discard-active">Удалить черновик тренировки</button></div>`}
function setMetricInput(e,ei,si,key,value,unit,max,step,label){return `<label class="set-metric"><input type="number" min="0" max="${max}" step="${step}" inputmode="${step==='1'?'numeric':'decimal'}" data-set="${ei},${si},${key}" value="${value??''}" aria-label="${label} ${si+1} ${esc(e.name)}"><span class="set-unit" aria-hidden="true">${unit}</span></label>`}
function activeExercise(e,ei){const timed=isTimed(e),loaded=isLoaded(e),distance=hasDistance(exercise(e.id)),fields=timed?(distance?2:1):3;return `<article class="card set-card"><div class="row between"><h3>${esc(e.name)}</h3><button class="exercise-technique" data-action="exercise-detail" data-id="${esc(e.id)}" aria-label="Информация об упражнении: ${esc(e.name)}">${icon('info')}</button></div><div class="set-rows">${e.sets.map((s,si)=>swipeSetRow('set',ei,si,`<div class="set-row ${timed?'':'strength-set'} ${s.done?'complete':''}" style="--set-fields:${fields};--set-controls:2"><span class="set-number">${si+1} подход</span>${timed?setTimeInput(e,ei,si,s):setMetricInput(e,ei,si,'weight',s.weight,'кг',2000,'.5',loaded?'Вес':'Дополнительный вес')}${timed?(distance?setMetricInput(e,ei,si,'distance',s.distance||'','м',100000,'1','Метры'):''):setMetricInput(e,ei,si,'reps',s.reps,'повт.',10000,'1','Повторы')}${timed?'':setTimeInput(e,ei,si,s)}${renderSetTimer(s,ei,si,e.name)}<button class="done ${s.done?'selected':''}" data-action="set-done" data-ei="${ei}" data-si="${si}" aria-label="${s.done?'Снять отметку':'Выполнить'} подход ${si+1} ${esc(e.name)}" aria-pressed="${s.done}">${icon('check')}</button></div>`)+renderSetRest(s,ei,si,e.name)).join('')}</div><div class="set-actions"><button class="set-add" data-action="add-set" data-ei="${ei}">${icon('plus')} Подход</button><button class="set-add" data-action="add-rest" data-ei="${ei}" ${e.sets.length?'':'disabled'}>${icon('plus')} Перерыв</button></div><input class="set-note" data-ex-note="${ei}" value="${esc(e.notes||'')}" placeholder="Добавить заметку…" aria-label="Заметка: ${esc(e.name)}"></article>`}

function renderDetail(){const w=state.workouts.find(w=>w.id===detailId);if(!w)return renderTop('Запись не найдена',false);return `<div class="workout-detail"><div class="training-heading"><h1 class="view-title">${esc(w.title)}</h1><button class="text-btn workout-share" data-action="share-workout" data-id="${esc(w.id)}" aria-label="Поделиться тренировкой"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M12 15V3m-4 4 4-4 4 4M7 10H5v11h14V10h-2"/></svg></button></div><div class="card workout-summary"><div class="row between workout-summary-header"><span class="sub">${dateLabel(w.start.slice(0,10))}<small class="workout-time-range">${w.start.slice(11,16)} — ${w.end.slice(11,16)}</small></span><button class="text-btn" data-action="edit-workout" data-id="${esc(w.id)}">${icon('pencil-simple')} Редактировать</button></div>${workoutSummaryMetrics(w)}</div>${w.warnings?.length?`<div class="source-note warn">${w.warnings.map(esc).join('<br>')}</div>`:''}${w.exercises.map(e=>`<article class="card set-card"><div class="row between"><h3 class="exercise-history-heading"><button class="exercise-history-name" data-action="exercise-history" data-id="${esc(e.id)}" aria-label="История упражнения: ${esc(e.name)}">${esc(e.name)}</button></h3><button class="exercise-technique" data-action="exercise-detail" data-id="${esc(e.id)}" aria-label="Информация об упражнении: ${esc(e.name)}">${icon('info')}</button></div>${e.sets.map((s,i)=>`<div class="read-set"><span class="type">${i+1}</span><strong>${isTimed(e)?durationText(s.seconds):s.weight?fmt(s.weight)+' кг':'Свой вес'}</strong><span>${isTimed(e)?s.distance?fmt(s.distance)+' м':'':s.reps+' повт.'+(s.seconds>0?'<small class="read-set-time">'+durationText(s.seconds)+'</small>':'')}</span></div>${renderReadRest(s)}`).join('')}${e.notes?`<p class="fineprint">${esc(e.notes)}</p>`:''}</article>`).join('')}${w.notes?`<div class="card"><h3>Заметки</h3><p class="sub" style="white-space:pre-wrap;margin-top:9px">${esc(w.notes)}</p></div>`:''}<p class="fineprint">Источник: ${esc(w.source)}.${volume(w)?'<br>* Объём по записанному внешнему весу. Вес тела не добавляется.':''}</p><button class="button" data-action="repeat-workout" data-id="${esc(w.id)}"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 7v5h-5M20 12a8 8 0 1 0-2.3 5.7"/></svg> Повторить тренировку</button><button data-action="delete-workout" data-id="${esc(w.id)}" class="text-btn delete-workout">Удалить запись</button></div>`}
function renderProfile(){return renderTop('Профиль',false)+`<div class="card"><div class="row">${icon('user-circle')}<div><h2>Happy Sport</h2><p class="sub" style="margin-top:4px">Тренировки и замеры</p></div></div></div><div class="section-title"><h2>Подключения</h2><span class="badge demo">Прототип</span></div><div class="card"><div class="setting-row"><div class="row">${icon('heartbeat')}<div><b>Apple Здоровье</b><small>Нужна нативная интеграция</small></div></div><span class="badge">Не подключено</span></div><div class="setting-row"><div class="row">${icon('headphones')}<div><b>Датчик пульса</b><small>Часы или совместимые наушники</small></div></div><button class="text-btn" data-action="connections">${icon('info')}</button></div><div class="setting-row"><div><b>Happy Meal</b><small>Потреблённая энергия · демо</small></div><button class="text-btn" data-action="energy">${icon('sliders-horizontal')}</button></div></div><div class="section-title"><h2>Мои данные</h2></div><div class="card"><div class="setting-row"><div><b>Тренировки</b><small>Записи этого браузера</small></div><strong>${state.workouts.length}</strong></div><div class="setting-row"><div><b>Замеры</b><small>Личные записи этого браузера</small></div><strong>${state.measurements.length}</strong></div><div class="setting-row"><div><b>Демонстрация пульса</b><small>Симулирует шкалу во время тренировки</small></div><input class="toggle" id="demo-pulse" type="checkbox" aria-label="Демонстрация пульса" ${state.demoPulse?'checked':''}></div></div><button class="button" data-action="export" style="margin-top:14px">${icon('download-simple')} Выгрузить все записи</button><button class="button" data-action="about" style="margin-top:10px">${icon('info')} О первом прототипе</button><p class="fineprint">Записи сохраняются в этом браузере. Для переноса или резервной копии выгрузи данные. Никакие записи не отправляются в HealthKit из этого прототипа.</p>`}
function updateClock(){if(!state.active)return;updateSetCountdown();const node=$('#active-clock');if(node){const diff=workoutActiveSeconds(state.active),h=Math.floor(diff/3600),m=Math.floor(diff/60)%60,s=diff%60;node.textContent=(h?String(h).padStart(2,'0')+':':'')+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')}if(state.demoPulse&&$('#pulse-value')){const n=124+Math.round(5*Math.sin(Date.now()/18000));$('#pulse-value').innerHTML=`${n} <small>уд/мин</small>`;$('#pulse-marker').style.left=(n-50)/150*100+'%'}}
setInterval(updateClock,1000);
function openSheet(title,html,kind=''){priorFocus=document.activeElement;sheetKind=kind;$('#modal-root').innerHTML=`<div class="overlay" id="overlay"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="handle"></div><div class="sheet-top"><h2 id="sheet-title">${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="Закрыть">${icon('x')}</button></div>${html}</section></div>`;document.body.style.overflow='hidden';$('.sheet [data-action="close"]').focus()}
function closeSheet(){if(!$('#modal-root'))return;$('#modal-root').innerHTML='';document.body.style.overflow='';sheetKind='';if(priorFocus?.isConnected)priorFocus.focus()}
function showStart(){if(state.active){goto('active');return}openSheet('Начать тренировку',`<div class="stack">${templates().map(t=>`<button class="card workout-row" data-action="start" data-id="${esc(t.id)}"><span class="symbol">${icon(kindIcon(t.kind))}</span><span class="grow"><h3>${esc(t.title)}</h3><small class="muted">${t.items.length} упражнений · можно изменить</small></span>${icon('play')}</button>`).join('')}</div><button class="button dashed" style="margin-top:13px" data-action="start-empty">${icon('plus')} Пустая тренировка</button>`)}
function previewTemplate(id){const t=templates().find(t=>t.id===id);openSheet(t.title,`<div class="large-icon">${icon(kindIcon(t.kind))}</div><p class="sheet-info">${esc(t.description||'Твой шаблон тренировки')}. Все значения можно изменить.</p>${Object.entries(phaseNames).map(([p,n])=>`<div class="phase-heading"><strong>${n}</strong></div>${t.items.filter(x=>x[1]===p).map(([eid,_,sets])=>`<div class="row between" style="padding:9px 0;font-size:13px"><span>${esc(exercise(eid)?.name||eid)}</span><small>${sets} подх.</small></div>`).join('')||'<div class="sub">Не задана</div>'}`).join('')}<div class="sheet-actions"><button class="button primary" data-action="start" data-id="${esc(t.id)}">${icon('play')} Начать</button><button class="button" data-action="edit-template" data-id="${esc(t.id)}">${icon('pencil-simple')} Изменить шаблон</button></div>`)}
function blankSet(e,phase='main'){return {type:phase,weight:0,reps:/reps|load/.test(e.profile)?10:0,seconds:/duration|hold|distance_time/.test(e.profile)?(phase==='main'?600:120):0,distance:0,done:false}}
function startWorkout(id,title){if(state.active){goto('active');toast('Продолжена текущая тренировка');return}const t=templates().find(x=>x.id===id)||{title:title||'Свободная тренировка',kind:'gym',items:[]};state.active={id:'local-'+Date.now(),title:t.title,kind:t.kind,icon:t.icon||null,start:localNow(),end:'',notes:'',source:'Моя запись',demo:false,exercises:t.items.map(([eid,phase,count])=>({id:eid,name:exercise(eid).name,phase,notes:'',sets:Array.from({length:count},()=>blankSet(exercise(eid),phase))}))};persist();goto('active')}
function showPicker(phase){openSheet('Добавить упражнение',`<input id="picker-phase" type="hidden" value="${phase}"><label class="search">${icon('magnifying-glass')}<input id="picker-search" placeholder="Название упражнения…" aria-label="Найти упражнение"></label><div id="picker-results" class="exercise-list">${allExercises().slice(0,18).map(e=>exerciseCard(e,'pick-exercise')).join('')}</div><button class="button dashed" style="margin-top:12px" data-action="custom-exercise">${icon('plus')} Создать своё</button>`,'picker')}
function pickExercise(id){const e=exercise(id),phase=$('#picker-phase')?.value||'main';if(!state.active){startWorkout(null);showPicker(phase);return}state.active.exercises.push({id:e.id,name:e.name,phase,notes:'',sets:[blankSet(e,phase)]});persist();closeSheet();render();toast('Упражнение добавлено')}
function showWorkoutForm(mode,id){const active=mode==='finish'||mode==='active',w=active?state.active:state.workouts.find(x=>x.id===id),start=w?.start||selectedDate+'T18:00',end=mode==='finish'?localNow():w?.end||selectedDate+'T19:00';openSheet(mode==='finish'?'Завершить тренировку':mode==='active'?'Время начала':w?'Редактировать запись':'Добавить тренировку',`<form id="workout-form" data-mode="${mode}" data-id="${esc(id||'')}"><label class="field">Название<input name="title" value="${esc(w?.title||'Тренажёрный зал')}" required maxlength="100"></label>${!w?`<label class="field">Вид<select name="kind"><option value="gym">Тренажёрный зал</option><option value="sea">Плавание в море</option><option value="bars">Турники</option><option value="cardio">Кардио</option></select></label>`:''}<label class="field">Начало<input name="start" type="datetime-local" step="1" required value="${start}"></label>${mode!=='active'?`<label class="field">Окончание<input name="end" type="datetime-local" step="1" required value="${end}"></label><label class="field">Заметка<textarea name="notes" placeholder="Упражнения, самочувствие, детали…">${esc(w?.notes||'')}</textarea></label>`:''}${mode==='finish'?`<p class="sheet-info">В журнал попадут отмеченные подходы: ${w.exercises.reduce((n,e)=>n+e.sets.filter(s=>s.done).length,0)}. Можно сохранить только время тренировки.</p>`:''}<div id="form-error" class="form-error" role="alert"></div><button class="button primary" type="submit">${icon('check')} ${mode==='finish'?'Завершить и сохранить':'Сохранить'}</button></form>`)}
function showExercise(id){const e=exercise(id);if(!e)return;const records=state.workouts.flatMap(w=>w.exercises.filter(x=>x.id===id).map(x=>{const max=Math.max(...x.sets.filter(s=>s.done).map(s=>isTimed(x)?s.seconds:isLoaded(x)?s.weight:s.reps),0);return{date:w.start.slice(0,10),max}})).sort((a,b)=>a.date.localeCompare(b.date));let chart='';if(records.length>1){const vals=records.map(r=>r.max),min=Math.min(...vals)*.85,max=Math.max(...vals)*1.1||1,pts=vals.map((v,i)=>`${15+i*310/(vals.length-1)},${105-(v-min)/(max-min||1)*90}`).join(' ');chart=`<div class="card chart-card"><div class="row between"><h3>Динамика</h3><small>${isTimed(e)?'сек':isLoaded(e)?'кг':'повторения'}</small></div><svg viewBox="0 0 340 120" role="img" aria-label="Лучший показатель по тренировкам"><path d="M15 105H325" stroke="#ffffff33" fill="none"/><polyline points="${pts}" stroke="#b6fff0" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" fill="none"/>${vals.map((v,i)=>`<circle cx="${15+i*310/(vals.length-1)}" cy="${105-(v-min)/(max-min||1)*90}" r="4" fill="#efffff"/>`).join('')}</svg><div class="chart-caption"><span>${shortDate(records[0].date)}</span><span>${shortDate(records.at(-1).date)}</span></div><p class="fineprint">Максимум за тренировку. ${isLoaded(e)?'Сравнивается записанный вес; количество повторов может отличаться.':'Вес тела здесь не учитывается.'}</p></div>`}openSheet(e.name,`<div class="row" style="margin-bottom:18px"><span class="placeholder" style="width:65px;height:65px">${icon('image')}</span><span><b style="font-size:13px">${esc(e.category)}</b><div class="sub">${esc(e.en||'Моё упражнение')}</div></span></div>${chart||'<p class="sheet-info">Динамика появится после нескольких записей этого упражнения.</p>'}${records.length?`<table class="data-table"><thead><tr><th>Тренировка</th><th>Лучшее значение</th></tr></thead><tbody>${records.slice(-5).reverse().map(r=>`<tr><td>${dateLabel(r.date)}</td><td>${fmt(r.max)} ${isTimed(e)?'сек':isLoaded(e)?'кг':'повт.'}</td></tr>`).join('')}</tbody></table>`:''}<div class="sheet-actions"><button class="button primary" data-action="use-exercise" data-id="${esc(id)}">${icon('plus')} Добавить в тренировку</button>${e.scope==='user'?`<button class="button" data-action="custom-exercise" data-id="${esc(id)}">${icon('pencil-simple')} Изменить упражнение</button>`:''}</div>`)}
function customExercise(id){const e=exercise(id);openSheet(e?'Моё упражнение':'Создать упражнение',`<form id="exercise-form" data-id="${esc(e?.id||'')}"><label class="field">Название<input name="name" required maxlength="120" value="${esc(e?.name||'')}" placeholder="Например, тяга моего тренажёра"></label><label class="field">Как ещё называешь<input name="aliases" value="${esc(e?.aliases?.join(', ')||'')}" placeholder="Короткие названия через запятую"></label><label class="field">Оборудование<input name="equipment" value="${esc(e?.equipment?.join(', ')||'')}" placeholder="Без оборудования, резинка, тренажёр…"></label><label class="field">Что записываем<select name="profile">${[['load_reps','Вес и повторения'],['reps','Повторения'],['duration','Время'],['distance_time','Время и расстояние'],['hold','Удержание по времени']].map(([v,t])=>`<option value="${v}" ${e?.profile===v?'selected':''}>${t}</option>`).join('')}</select></label><button class="button primary" type="submit">${icon('check')} Сохранить в мою библиотеку</button></form>`)}
function templateItemRow(item=['','main',3]){return `<div class="card template-item" style="padding:11px;margin-bottom:10px"><select name="exerciseId" aria-label="Упражнение шаблона" required style="width:100%;font-size:12px"><option value="">Выбрать упражнение…</option>${allExercises().map(e=>`<option value="${esc(e.id)}" ${e.id===item[0]?'selected':''}>${esc(e.name)}</option>`).join('')}</select><div class="row" style="margin-top:8px"><input type="hidden" name="phase" value="${esc(item[1]||'main')}"><span class="grow sub">Подходы</span><input type="number" name="count" aria-label="Число подходов" min="1" max="50" value="${item[2]}" style="width:57px;padding:10px 5px;text-align:center"><button class="icon-btn" type="button" data-action="remove-template-item" aria-label="Убрать упражнение из шаблона">${icon('x')}</button></div></div>`}
function editTemplate(id,fromActive=false){const t=templates().find(t=>t.id===id),w=fromActive?state.active:null;openSheet(t?'Изменить тренировку':'Новая тренировка',`<form id="template-form" data-id="${esc(id||'')}"><label class="field">Название<input name="title" required maxlength="100" value="${esc(t?.title||w?.title||'')}" placeholder="Моя тренировка"></label><label class="field">Вид<select name="kind">${[['gym','Зал'],['sea','Море'],['bars','Турники'],['cardio','Кардио']].map(([v,n])=>`<option value="${v}" ${(t?.kind||w?.kind)===v?'selected':''}>${n}</option>`).join('')}</select></label><div id="template-items">${(t?.items||w?.exercises.map(e=>[e.id,e.phase,e.sets.length])||[['','main',3]]).map(templateItemRow).join('')}</div><button class="button dashed" type="button" data-action="add-template-item">${icon('plus')} Упражнение</button><button class="button primary" type="submit" style="margin-top:14px">${icon('check')} Сохранить тренировку</button></form>`)}
function measureForm(edit=false){const {cur}=measurePair();openSheet(edit?'Исправить замеры':'Новый замер',`<form id="measure-form"><label class="field">Дата<input name="date" type="date" required value="${edit?cur.date:dayNow()}"></label><p class="sheet-info">Заполни только то, что измерил. Остальное останется пустым.</p><div class="twocol">${MF.map(([k,n])=>`<label class="field">${n}, ${k==='weight'?'кг':'см'}<input name="${k}" type="number" min="1" max="500" step=".1" inputmode="decimal" value="${edit&&cur.values[k]!=null?cur.values[k]:''}" placeholder="—"></label>`).join('')}</div><div id="form-error" class="form-error" role="alert"></div><button class="button primary" type="submit">${icon('check')} Сохранить замер</button></form>`)}
function energyForm(){const e=state.energy;openSheet('Баланс энергии',`<p class="sheet-info">Пример общего дня Happy Sport и Happy Meal. Меняй цифры — обе дуги обновляются на одной шкале. Реальная синхронизация пока не подключена.</p><form id="energy-form"><div class="twocol">${[['burn','Общий расход, ккал'],['intake','Потреблено, ккал'],['steps','Шаги'],['training','На тренировке, ккал'],['minutes','Активность, мин']].map(([k,n])=>`<label class="field">${n}<input name="${k}" type="number" min="0" max="${k==='steps'?100000:10000}" step="1" required value="${e[k]}"></label>`).join('')}</div><p class="sheet-info">Энергия тренировки — часть расхода. Повторно её не прибавляем. Цвета не обозначают «хорошо» или «плохо».</p><div id="form-error" class="form-error"></div><button class="button primary" type="submit">Показать на главной</button></form>`)}
function voiceSheet(){openSheet('Записать словами',`<p class="sheet-info">${state.active?'Добавим к текущей тренировке: '+esc(state.active.title):'Начнём свободную тренировку и запишем подходы.'}</p><textarea class="voice-area" id="voice-text" aria-label="Текст записи" placeholder="Жим лёжа 60 кг, 3 подхода по 10"></textarea><div class="voice-examples"><button data-action="example" data-text="Жим лёжа 60 кг, 3 подхода по 10">Жим 60 × 10</button><button data-action="example" data-text="Подтягивания 3 подхода по 8">Подтягивания</button><button data-action="example" data-text="Заметка: сегодня было легко">Заметка</button></div><div id="voice-feedback" class="feedback" role="status"></div><div id="voice-choice"></div><div class="twocol"><button class="button" data-action="record-voice">${icon('microphone')} Диктовать</button><button class="button primary" data-action="parse-voice">${icon('check')} Записать</button></div><p class="fineprint">В прототипе — разбор простых фраз. Произвольный ИИ и ответы о технике ещё не подключены. Можно использовать диктовку клавиатуры.</p>`,'voice')}
function parseVoice(forced){const raw=$('#voice-text').value.trim();let text=raw.toLowerCase().replaceAll('ё','е').replaceAll(',','.');const words={один:1,одна:1,два:2,две:2,три:3,четыре:4,пять:5,шесть:6,семь:7,восемь:8,девять:9,десять:10,одиннадцать:11,двенадцать:12,тринадцать:13,четырнадцать:14,пятнадцать:15,шестнадцать:16,семнадцать:17,восемнадцать:18,девятнадцать:19,двадцать:20,тридцать:30,сорок:40,пятьдесят:50,шестьдесят:60,семьдесят:70,восемьдесят:80,девяносто:90,сто:100};text=text.replace(/[а-я]+/g,w=>words[w]??w);if(!raw)return;const err=t=>{$('#voice-feedback').textContent=t};if(/^заметка\s*:/.test(text)){if(!state.active)startWorkout();const old=state.active.notes;state.active.notes+=(old?'\n':'')+raw.replace(/^заметка\s*:/i,'').trim();persist();closeSheet();goto('active');toast('Заметка сохранена',()=>{state.active.notes=old;persist();render()});return}
let candidates=[];if(forced)candidates=[exercise(forced)];else if(/подтяг/.test(text))candidates=[exercise('pull-up')];else if(/отжим/.test(text))candidates=[exercise('push-up')];else if(/присед/.test(text)&&/штанг/.test(text))candidates=[exercise('barbell-back-squat')];else if(/жим.*леж/.test(text))candidates=[exercise(/гантел/.test(text)?'dumbbell-bench-press':'barbell-bench-press')];else if(/жим/.test(text))candidates=[exercise('barbell-bench-press'),exercise('barbell-incline-press'),exercise('barbell-overhead-press')];else candidates=allExercises().filter(e=>[e.name,...e.aliases].some(n=>n.length>3&&text.includes(n.toLowerCase().replaceAll('ё','е'))));
if(candidates.length!==1){$('#voice-choice').innerHTML=`<label class="field">${candidates.length?'Какое упражнение?':'Выбери упражнение для этой записи'}<select id="voice-exercise"><option value="">Выбрать…</option>${(candidates.length?candidates:allExercises()).map(e=>`<option value="${esc(e.id)}">${esc(e.name)}</option>`).join('')}</select></label>`;err('Числа не записаны. Уточни упражнение и нажми «Записать».');return}
const e=candidates[0];let weight=+(text.match(/(\d+(?:\.\d+)?)\s*(?:кг|kg)/)?.[1]||0),count=+(text.match(/(\d+)\s*подх/)?.[1]||1),reps=+(text.match(/(?:по|на)\s*(\d+)/)?.[1]||text.match(/(\d+)\s*(?:повт|раз)/)?.[1]||0);const mult=text.match(/(\d+)\s*[хx×]\s*(\d+)/);if(mult){if(!weight){weight=+mult[1];reps=+mult[2]}else{count=+mult[1];reps=+mult[2]}}const minutes=+(text.match(/(\d+(?:\.\d+)?)\s*мин/)?.[1]||0);if(isTimed(e)?!minutes:!reps){err(isTimed(e)?'Не вижу длительность. Например: «Плавание 12 минут».':'Не вижу повторения. Например: «3 подхода по 10».');return}if(isLoaded(e)&&!text.match(/(\d+(?:\.\d+)?)\s*(кг|kg)/)&&!mult){err('Укажи вес в кг. Его нельзя определить из этой фразы.');return}if(count>50||reps>1000||weight>2000){err('Проверь числа: похоже на ошибку распознавания.');return}const snapshot=clone(state.active);if(!state.active)startWorkout();let target=state.active.exercises.findLast(x=>x.id===e.id&&x.phase==='main');if(!target){target={id:e.id,name:e.name,phase:'main',sets:[],notes:''};state.active.exercises.push(target)}target.sets.push(...Array.from({length:count},()=>({type:'main',weight,reps,seconds:minutes*60,distance:0,done:true})));persist();closeSheet();goto('active');toast(`${e.name}: ${count} подход${plural(count)} записано`,()=>{state.active=snapshot;persist();render()})}
function dictate(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){$('#voice-feedback').textContent='Здесь браузерная диктовка недоступна. Используй микрофон клавиатуры или введи текст.';$('#voice-text').focus();return}const recognition=new SR();recognition.lang='ru-RU';recognition.interimResults=true;recognition.onresult=e=>{if($('#voice-text'))$('#voice-text').value=Array.from(e.results).map(x=>x[0].transcript).join(' ')};recognition.onerror=()=>{if($('#voice-feedback'))$('#voice-feedback').textContent='Не удалось получить речь. Попробуй диктовку клавиатуры или текст.'};recognition.onend=()=>{if($('#voice-feedback'))$('#voice-feedback').textContent='Проверь распознанный текст и нажми «Записать».'};$('#voice-feedback').textContent='Слушаю… Распознавание выполняет браузер.';try{recognition.start()}catch{recognition.onerror()}}
function downloadData(){const blob=new Blob([JSON.stringify({app:'Happy Sport',version:1,exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'}),a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download='happy-sport-backup-'+dayNow()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);toast('Подготовлена копия всех записей')}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;switch(a){
case'navigate':goto(b.dataset.view);break;case'back':goto(state.active&&view==='active'?'diary':'journal');break;case'close':closeSheet();break;case'undo':if(undoAction)undoAction();$('#toast-root').innerHTML='';undoAction=null;break;
case'start-menu':showStart();break;case'resume':goto('active');break;case'start':startWorkout(id);break;case'start-empty':startWorkout();break;case'preview-template':previewTemplate(id);break;case'past':showWorkoutForm('past');break;case'finish':showWorkoutForm('finish');break;case'edit-active-time':showWorkoutForm('active');break;case'edit-workout':showWorkoutForm('edit',id);break;case'open-workout':detailId=id;goto('detail');break;
case'templates':libraryTab='templates';goto('library');break;case'library-tab':libraryTab=id;render();break;case'scope':libraryScope=id;render();break;case'category':category=id;render();break;case'exercise-detail':showExercise(id);break;case'custom-exercise':customExercise(id);break;case'journal-tab':journalTab=id;render();break;case'history-filter':historyFilter=id;render();break;case'period':period=id;render();break;case'amplify':amplify=+id;render();break;
case'changes':{const {cur,old}=measurePair();openSheet('Что изменилось',`<p class="sheet-info">${dateLabel(old.date)} → ${dateLabel(cur.date)}. Все значения в сантиметрах, вес — в килограммах.</p><div class="card">${measureRows(cur,old)}</div><p class="fineprint">Силуэт — схема изменения замеров, а не точная реконструкция тела. Размеры без пары измерений не сравниваются.</p>`);break}
case'add-measure':measureForm();break;case'edit-measure':measureForm(true);break;case'energy':energyForm();break;case'voice':voiceSheet();break;case'example':$('#voice-text').value=b.dataset.text;$('#voice-feedback').textContent='Пример готов к записи';break;case'parse-voice':parseVoice($('#voice-exercise')?.value||null);break;case'record-voice':dictate();break;
case'add-exercise':showPicker(b.dataset.phase);break;case'pick-exercise':pickExercise(id);break;case'use-exercise':if(!state.active)startWorkout();pickExercise(id);goto('active');break;case'add-set':{const e=state.active.exercises[+b.dataset.ei];e.sets.push({...clone(e.sets.at(-1)||blankSet(exercise(e.id),e.phase)),done:false,restDone:false,restSeconds:undefined});persist();render();break}
case'set-done':{const e=state.active.exercises[+b.dataset.ei],s=e.sets[+b.dataset.si];if(!s.done&&!canCompleteSet(e,s,+b.dataset.ei,+b.dataset.si)){toast(isTimed(e)?'Укажи длительность подхода':'Укажи количество повторений');break}if(!s.done)finishWorkTimer(+b.dataset.ei,+b.dataset.si);s.done=!s.done;onSetMarked(+b.dataset.ei,+b.dataset.si,s.done);persist();const y=window.scrollY;render();window.scrollTo(0,y);break}
case'pulse-toggle':state.demoPulse=!state.demoPulse;persist();render();break;case'save-template':editTemplate(null,true);break;case'new-template':editTemplate();break;case'edit-template':editTemplate(id);break;case'add-template-item':$('#template-items').insertAdjacentHTML('beforeend',templateItemRow());break;case'remove-template-item':b.closest('.template-item').remove();break;
case'discard-active':{const old=clone(state.active);state.active=null;persist();goto('diary');toast('Черновик удалён',()=>{state.active=old;persist();goto('active')});break}
case'repeat-workout':{if(state.active){goto('active');toast('Сначала заверши текущую тренировку');break}const src=state.workouts.find(w=>w.id===id);state.active={...clone(src),countdown:null,pauses:[],id:'local-'+Date.now(),start:localNow(),end:'',source:'Моя запись',warnings:[],notes:'',exercises:src.exercises.map(e=>({...clone(e),sets:e.sets.map(s=>({...s,done:false,restDone:false}))}))};persist();goto('active');break}
case'activity-start':{const act=SEED.activities.find(a=>a.id===id);startWorkout(null,act.name_ru);break}
case'delete-workout':{const old=state.workouts.find(w=>w.id===id);state.workouts=state.workouts.filter(w=>w.id!==id);persist();goto('journal');toast('Запись удалена',()=>{state.workouts.push(old);persist();render()});break}
case'export':downloadData();break;case'connections':openSheet('Пульс и Apple Здоровье',`<p class="sheet-info">В нативном приложении датчик будет давать текущий пульс, а итог тренировки — сохраняться в Apple Здоровье. Здесь можно проверить только интерфейс.</p><div class="source-note">Одна тренировка — одна запись. Если её уже записывает другое приложение, Happy Sport должен связать журнал с этой сессией, чтобы не создавать дубль.</div><p class="fineprint">Получение показаний с конкретных часов и наушников требует отдельной проверки интеграции на устройстве.</p>`);break;
case'about':openSheet('Happy Sport · прототип 1',`<p class="sheet-info">Дневник упражнений с голосовым и текстовым вводом, своими тренировками и библиотекой.</p><div class="card"><div class="setting-row"><b>Работает сейчас</b></div><p class="sub">Начало и завершение тренировки, подходы и заметки, разминка и заминка, библиотека, собственные упражнения и шаблоны, замеры, история, локальное сохранение и выгрузка.</p></div><div class="card" style="margin-top:12px"><div class="setting-row"><b>Пока демонстрация</b></div><p class="sub">Пульс, энергия и связь с Happy Meal. Разбор фраз упрощён; полноценный ИИ, HealthKit и синхронизация между устройствами ещё не подключены.</p></div><p class="fineprint">Основа каталога: 121 самостоятельно систематизированное упражнение, 7 кардио-действий и 2 упражнения из твоих записей. Иконки — Phosphor (MIT).</p>`);break;
}});
document.addEventListener('input',ev=>{const t=ev.target;if(t.id==='library-search'){query=t.value;$('#library-results').innerHTML=libraryResults()}if(t.id==='picker-search')$('#picker-results').innerHTML=allExercises().filter(e=>matches(e,t.value)).slice(0,35).map(e=>exerciseCard(e,'pick-exercise')).join('')||'<div class="empty">Ничего не найдено. Можно создать своё упражнение.</div>';if(t.dataset.set&&state.active){const [ei,si,key]=t.dataset.set.split(','),s=state.active.exercises[+ei].sets[+si],val=Math.max(0,Number(t.value)||0);s[key==='minutes'?'seconds':key]=key==='minutes'?val*60:val;persist()}if(t.dataset.exNote!=null){state.active.exercises[+t.dataset.exNote].notes=t.value;persist()}if(t.id==='active-note'){state.active.notes=t.value;persist()}});
document.addEventListener('change',ev=>{const t=ev.target;if(t.id==='day-picker'){selectedDate=t.value;render()}if(t.id==='measure-date'){measureDate=t.value;render()}if(t.id==='demo-pulse'){state.demoPulse=t.checked;persist()}if(t.dataset.setType){const [ei,si]=t.dataset.setType.split(',').map(Number);state.active.exercises[ei].sets[si].type=t.value;persist()}});
document.addEventListener('submit',ev=>{const form=ev.target;ev.preventDefault();const f=new FormData(form),get=k=>String(f.get(k)||''),error=t=>{$('#form-error').textContent=t};
if(form.id==='workout-form'){const start=get('start'),end=get('end'),mode=form.dataset.mode;if(mode==='active'){if(start>localNow()){error('Начало текущей тренировки не может быть в будущем.');return}state.active.start=start;state.active.title=get('title').trim();state.active.icon=workoutIconValue(f.get('icon'));persist();closeSheet();render();return}if(end<start){error('Окончание должно быть позже начала. Можно выбрать следующий день.');return}let w;if(mode==='finish'){w=clone(state.active);closeWorkoutPause(w,end);w.exercises=w.exercises.map(e=>({...e,sets:e.sets.filter(s=>s.done)})).filter(e=>e.sets.length);state.active=null}else if(mode==='edit')w=state.workouts.find(x=>x.id===form.dataset.id);else w={id:'manual-'+Date.now(),kind:get('kind'),source:'Моя запись',exercises:[],demo:false,warnings:[]};Object.assign(w,{title:get('title').trim(),icon:workoutIconValue(f.get('icon')),start,end,notes:get('notes'),duration:workoutActiveSeconds(w,start,end)});if(mode==='edit'){w.source+=' · время/заметка изменены';w.warnings=[]}else state.workouts.push(w);persist();detailId=w.id;goto('detail');toast('Тренировка сохранена в журнале');return}
if(form.id==='exercise-form'){const id=form.dataset.id||'custom-'+Date.now(),entry={id,name:get('name').trim(),en:'',aliases:get('aliases').split(',').map(x=>x.trim()).filter(Boolean),equipment:get('equipment').split(',').map(x=>x.trim()).filter(Boolean),category:'Мои упражнения',profile:get('profile'),scope:'user',loadBasis:null,muscleGroups:f.getAll('muscleGroups')};if(!entry.name)return;const old=state.customExercises.findIndex(e=>e.id===id);if(old>=0)state.customExercises[old]=entry;else if(SEED.exercises.some(e=>e.id===id)){state.exerciseOverrides??={};state.exerciseOverrides[id]=entry}else state.customExercises.push(entry);persist();closeSheet();libraryTab='exercises';libraryScope='all';libraryMuscle='all';librarySport='all';category='all';query='';goto('library');toast('Упражнение сохранено');return}
if(form.id==='template-form'){const items=[...form.querySelectorAll('.template-item')].map(row=>[row.querySelector('[name=exerciseId]').value,row.querySelector('[name=phase]').value,+row.querySelector('[name=count]').value]);const id=form.dataset.id||'template-'+Date.now(),t={id,title:get('title').trim(),kind:get('kind'),items};if(baseTemplates.some(x=>x.id===id)){state.templateOverrides??={};state.templateOverrides[id]=t}else{const index=state.templates.findIndex(x=>x.id===id);if(index>=0)state.templates[index]=t;else state.templates.push(t)}persist();libraryTab='templates';goto('library');toast('Шаблон сохранён');return}
if(form.id==='measure-form'){const values={};MF.forEach(([k])=>{if(get(k)!=='')values[k]=+get(k)});if(!Object.keys(values).length){error('Внеси хотя бы один замер.');return}const date=get('date'),idx=state.measurements.findIndex(m=>m.date===date),m={date,values,source:'Мой замер',note:''};if(idx>=0)state.measurements[idx]=m;else state.measurements.push(m);state.measurements.sort((a,b)=>a.date.localeCompare(b.date));measureDate=date;persist();journalTab='measurements';goto('journal');toast('Замер сохранён');return}
if(form.id==='energy-form'){if(+get('training')>+get('burn')){error('Энергия тренировки не может превышать общий расход.');return}Object.keys(state.energy).forEach(k=>state.energy[k]=+get(k));persist();goto('diary');toast('Демонстрационные показатели обновлены')}
});
document.addEventListener('keydown',ev=>{if(!$('#overlay'))return;if(ev.key==='Escape'){closeSheet();return}if(ev.key==='Tab'){const list=[...$('.sheet').querySelectorAll('button,input,textarea,select,a')].filter(el=>!el.disabled&&el.offsetParent!==null),first=list[0],last=list.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus()}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus()}}});
render();

function workoutPulseSamples(w){return (Array.isArray(w.heartRateSamples)?w.heartRateSamples:[]).filter(s=>s&&Number.isFinite(s.bpm)&&s.bpm>0&&Number.isFinite(s.elapsedSeconds)&&s.elapsedSeconds>=0).sort((a,b)=>a.elapsedSeconds-b.elapsedSeconds)}
function workoutAveragePulse(w){if(Number.isFinite(w.avgHeartRate)&&w.avgHeartRate>0)return w.avgHeartRate;const samples=workoutPulseSamples(w);return samples.length?samples.reduce((n,s)=>n+s.bpm,0)/samples.length:null}
function workoutDistance(w){const sets=w.exercises.flatMap(e=>isTimed(e)?e.sets.filter(s=>s.done&&Number.isFinite(s.distance)&&s.distance>0):[]);return sets.length?sets.reduce((n,s)=>n+s.distance,0):null}
function workoutSummaryMetrics(w){
 const pulse=workoutAveragePulse(w),secs=Math.max(0,w.duration||0),hours=Math.floor(secs/3600);
 const time=hours?hours+':'+String(Math.floor(secs%3600/60)).padStart(2,'0'):Math.floor(secs/(secs>=60?60:1));
 const unit=hours?'ч:мин':secs>=60?'мин':'сек';
 const kcal=Number.isFinite(w.energyKcal)&&w.energyKcal>=0?Math.round(w.energyKcal):'—';
 return `<div class="workout-metrics" aria-label="Показатели тренировки"><button class="workout-heart" data-action="workout-pulse" data-id="${esc(w.id)}" aria-label="Средний пульс и график"><strong>${icon('heartbeat')}<span>${pulse==null?'—':Math.round(pulse)}</span></strong><small>уд/мин</small></button><div aria-label="Продолжительность"><strong>${time}</strong><small>${unit}</small></div><div><strong>${w.exercises.reduce((n,e)=>n+e.sets.length,0)}</strong><small>подходы</small></div><div><strong>${kcal}</strong><small>ккал</small></div></div>${workoutExtraMetrics(w)}`
}
function workoutExtraMetrics(w){const v=volume(w),d=workoutDistance(w);if(!(v>0)&&d==null)return '';return `<div class="workout-extra-metrics">${v>0?`<div><strong>${fmt(v>=1000?v/1000:v)} ${v>=1000?'т':'кг'}</strong><small>Тоннаж</small></div>`:''}${d!=null?`<div><strong>${fmt(d>=1000?d/1000:d)} ${d>=1000?'км':'м'}</strong><small>Дистанция</small></div>`:''}</div>`}

function showWorkoutPulse(w){const samples=workoutPulseSamples(w),avg=workoutAveragePulse(w);let chart='';if(samples.length>1){const first=samples[0].elapsedSeconds,last=samples.at(-1).elapsedSeconds,min=Math.max(0,Math.min(...samples.map(s=>s.bpm))-10),max=Math.max(...samples.map(s=>s.bpm))+10;const pts=samples.map(s=>`${12+(s.elapsedSeconds-first)/Math.max(1,last-first)*296},${138-(s.bpm-min)/(max-min)*120}`).join(' ');chart=`<svg class="workout-pulse-chart" viewBox="0 0 320 160" role="img" aria-label="Пульс по ходу тренировки"><path d="M12 138H308" fill="none" stroke="#ffffff40"/><polyline points="${pts}" fill="none" stroke="#ffb9e8" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg><div class="row between sub"><span>${durationText(first)}</span><span>${durationText(last)}</span></div><p class="fineprint">${Math.round(min)}–${Math.round(max)} уд/мин · ${samples.length} измерений</p>`}else chart='<p class="sheet-info">Для этой тренировки нет серии измерений пульса. График появится после подключения датчика или импорта данных.</p>';openSheet('Пульс тренировки',`${avg==null?'':`<p class="pulse-value">${Math.round(avg)} <small>уд/мин в среднем</small></p>`}${chart}`)}
async function shareWorkout(w){const v=volume(w),d=workoutDistance(w),p=workoutAveragePulse(w);const text=`${w.title}\n${dateLabel(w.start.slice(0,10))} · ${w.start.slice(11,16)}–${w.end.slice(11,16)}\n${durationText(w.duration)}${v>0?'\nТоннаж: '+fmt(v)+' кг':''}${d!=null?'\nДистанция: '+fmt(d)+' м':''}${p!=null?'\nСредний пульс: '+Math.round(p)+' уд/мин':''}`;if(navigator.share){try{await navigator.share({title:w.title,text});return}catch(e){if(e.name==='AbortError')return}}try{await navigator.clipboard.writeText(text);toast('Сводка тренировки скопирована')}catch{openSheet('Поделиться тренировкой',`<textarea class="plan-copy" readonly aria-label="Сводка тренировки">${esc(text)}</textarea>`)}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!['workout-pulse','share-workout'].includes(b.dataset.action))return;const w=state.workouts.find(w=>w.id===b.dataset.id);if(!w)return;if(b.dataset.action==='workout-pulse')showWorkoutPulse(w);else shareWorkout(w)});
